{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "In a crossover study in 12 healthy subjects, the absolute oral bioavailability of 17-beclomethasone monopropionate (17-BMP), the active metabolite of beclomethasone dipropionate, was 41% (90% CI 31-54%) versus IV; this molecule differs from the query only by a 17-propionate ester instead of the 17-hydroxy group and is the closest direct human F measurement.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Nomegestrol acetate, a structurally related steroidal drug, had an absolute oral bioavailability of 63.4% in healthy women, supporting high oral absorption for the steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Ursodeoxycholic acid, a steroid with multiple hydroxyls, showed 50% systemic availability in healthy subjects, indicating that polar steroids can still achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Chlormadinone acetate, a chlorinated steroid, has approximately 100% oral bioavailability in humans, supporting high F for chlorinated steroid structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danazol, a highly lipophilic, poorly water-soluble steroid, had only 11±5.2% absolute oral bioavailability in the fasted state; this low value is dissolution-limited and not mechanistically transferable to the more polar, hydroxylated corticosteroid query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogue, 17-BMP, has a measured absolute oral bioavailability of 41% in humans, well above the 20% threshold. Additional steroidal drugs (nomegestrol acetate 63%, UDCA 50%, chlormadinone acetate ~100%) support high oral F for this scaffold. The only low-F steroid evidence (danazol fasted) is solubility-limited and not applicable to the polar, hydroxylated query. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule (beclomethasone free base); the closest evidence is for 17-BMP, which differs by a 17-propionate ester.",
    "Fed/fasted conditions for the query are unspecified, and danazol data show that condition can strongly affect F for poorly soluble steroids."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

